from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

app = FastAPI()

call_count = 0

def dep_no_scopes():
    global call_count
    call_count += 1
    return "value"

@app.get("/")
def read_root(d1: str = Depends(dep_no_scopes), d2: str = Depends(dep_no_scopes)):
    return {"d1": d1, "d2": d2}

client = TestClient(app)

def test_cache_no_scopes():
    global call_count
    call_count = 0
    response = client.get("/")
    assert response.status_code == 200
    assert call_count == 1  # Should be cached, so only called once

if __name__ == "__main__":
    try:
        test_cache_no_scopes()
        print("Test passed: Dependency without scopes was cached.")
    except AssertionError as e:
        print(f"Test failed: Dependency without scopes was NOT cached. call_count: {call_count}")
        raise e

